args.sparql:
SELECT ?person ?birthDate ?label WHERE {
  VALUES ?person { dbr:Jayme_de_Almeida dbr:Elmina_Shepard_Taylor }
  OPTIONAL { ?person dbo:birthDate ?d1 }
  OPTIONAL { ?person dbp:birth_date ?d2 }
  BIND(coalesce(?d1, ?d2) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = 'en' || lang(?label) = '') }
}
ORDER BY ASC(?birthDate)
LIMIT 1

